<script lang="ts">
	import type { Snippet } from "svelte";
	import type { MenuItem as Item } from "./MenuTypes.js";
	import MenuItem from "./MenuItem.svelte";
	import Popover from "./Popover.svelte";
	import UiContent from "./UIContent.svelte";
	import { arrowNavigation, matchOnType } from "../util/keyboard.svelte.js";

	/**
	 * @description
	 * A dropdown menu built on the Popover component. Handles keyboard navigation (arrow keys, type-ahead)
	 * and renders MenuItem entries. Uses menu tokens for styling via the Popover's CSS variable overrides.
	 * @example
	 * <MenuDropdown
	 *     trigger="Options"
	 *     items={[
	 *         { type: 'item', text: 'Edit', onclick: () => {} },
	 *         { type: 'divider' },
	 *         { type: 'item', text: 'Delete', color: 'alert', onclick: () => {} },
	 *     ]}
	 * />
	 */
	let {
		open = $bindable(false),
		items,
		trigger: triggerProp,
		placement = "bottom-start",
		width,
		maxWidth,
	}: {
		/** Whether the menu is open */
		open?: boolean;
		/** The items to display in the menu */
		items: Item[];
		/** The trigger snippet or string */
		trigger: string | Snippet<[{ toggle: () => void; isOpen: boolean; triggerAttrs?: Record<string, string> }]>;
		/** Placement: "bottom-start" (default), "bottom", "bottom-end" */
		placement?: "bottom-start" | "bottom" | "bottom-end";
		/** The width of the menu */
		width?: string;
		/** The max width of the menu */
		maxWidth?: string;
	} = $props();

	let menuEl: HTMLDivElement | null = $state(null);
	let keyboardHasFocus: boolean = $state(false);

	function handleOpen() {
		window.addEventListener("keydown", onkeydown);
	}

	function handleClose() {
		window.removeEventListener("keydown", onkeydown);
		keyboardHasFocus = false;
	}

	function onkeydown(e: KeyboardEvent) {
		if (!open || !menuEl) return;
		
		switch (e.key) {
			case "ArrowDown":
				e.preventDefault();
				arrowNavigation(menuEl, "down");
				matchOnType(menuEl, e);
				keyboardHasFocus = true;
				break;
			case "ArrowUp":
				e.preventDefault();
				arrowNavigation(menuEl, "up");
				matchOnType(menuEl, e);
				keyboardHasFocus = true;
				break;
			case "Enter":
			case " ":
				e.preventDefault();
				(document.activeElement as HTMLElement)?.click();
				break;
			case "Tab":
				e.preventDefault();
				open = false;
				break;
			default:
				matchOnType(menuEl, e);
		}
	}

	function handleMouseover(e: MouseEvent, item: Item, index: number) {
		if (item.type === "item") {
			keyboardHasFocus = false;
		}
	}

	function handleSelect(item: Item, index: number) {
		open = false;
	}

	let scrollable = $derived.by(() => {
		if (!menuEl) return false;
		return menuEl.scrollHeight > menuEl.clientHeight;
	});

	const isStringTrigger = $derived(typeof triggerProp === "string");
</script>

<UiContent>
	<Popover
		bind:open
		{placement}
		fallbacks={["flip-block", "flip-inline"]}
		offset="0.5rem"
		{width}
		maxWidth={maxWidth || "50ch"}
		maxHeight="calc(50vh - 2rem)"
		onopen={handleOpen}
		onclose={handleClose}
		class="MenuDropdownPopover"
		--popover-background="var(--menu-background-color)"
		--popover-border="var(--menu-border-size) var(--menu-border-style) var(--menu-border-color)"
		--popover-border-radius="var(--menu-border-radius)"
		--popover-shadow="0 0.5rem 1rem var(--shadow-color)"
	>
		{#snippet trigger(popoverArgs)}
			{#if isStringTrigger}
				<button
					type="button"
					class="button"
					{...popoverArgs.triggerAttrs}
					aria-haspopup="menu"
				>
					{triggerProp}
				</button>
			{:else if typeof triggerProp !== "string"}
				{@render triggerProp({ 
					toggle: popoverArgs.toggle, 
					isOpen: popoverArgs.isOpen,
					triggerAttrs: popoverArgs.triggerAttrs,
				})}
			{/if}
		{/snippet}

		<div
			class="MenuDropdownContent"
			class:scrollable
			role="menu"
			bind:this={menuEl}
		>
			<ul>
				{#each items as item, index}
					<MenuItem
						{keyboardHasFocus}
						onmouseover={handleMouseover}
						onselect={handleSelect}
						{item}
						{index}
					/>
				{/each}
			</ul>
		</div>
	</Popover>
</UiContent>

<style>
	.MenuDropdownContent {
		overflow-x: clip;
		overflow-y: auto;
		scrollbar-width: thin;
		scrollbar-color: var(--scrollbar-color);
	}

	.MenuDropdownContent.scrollable {
		border-top-right-radius: 0;
		border-bottom-right-radius: 0;
	}

	.MenuDropdownContent :global(:has(li:last-of-type[data-type="item"])) {
		padding-block-end: 0.5rem;
	}

	ul {
		margin: 0;
		list-style: none;
		padding: 0;
	}
</style>
